bg=7
out=[[bg]*7 for _ in range(19)]
patterns={1:[[1,0,1],[1,0,1],[1,1,1]],4:[[1,0,0],[1,1,0],[1,0,1]],6:[[1,1,1],[0,1,0],[1,1,1]]}
for start,color in [(1,1),(7,4),(13,6)]:
    for dr in range(5):
        for dc in range(5):
            if dr in (0,4) or dc in (0,4): out[start+dr][1+dc]=color
            else: out[start+dr][1+dc]=color if patterns[color][dr-1][dc-1] else bg
print('\n'.join(' '.join(map(str,r)) for r in out))

